import pytest

from bedrock_protocol import v1001, v2168, v2225

Packet = v2225.ClientboundDebugRendererPacket

# TODO: confirm against BDS: gophertunnel's packet.ClientBoundDebugRenderer still writes the pre-cereal body,
# BDS dumps a presence flag ahead of the marker and a one-int32 colour, so gophertunnel has to give.
# TODO: patched, confirm against BDS
# generated by gophertunnel b8bd735, protocol.Writer over the dump's field list:
# {Type: "adddebugmarkercube", Marker: {"marker", Vec3{1, 2, 3}, 0x44556677, 1500}}
ADD_CUBE = bytes.fromhex(
    "1261646464656275676d61726b65726375626501066d61726b65720000803f000000400000404077665544dc05000000000000"
)

# TODO: patched, confirm against BDS
# generated by gophertunnel b8bd735, protocol.Writer over the dump's field list:
# Type invalid, no marker
INVALID = bytes.fromhex("07696e76616c696400")

# TODO: patched, confirm against BDS
# generated by gophertunnel b8bd735, protocol.Writer over the dump's field list:
# {Type: "cleardebugmarkers", Marker: {"", Vec3{}, -1, 255}}
CLEAR_WITH_MARKER = bytes.fromhex(
    "11636c65617264656275676d61726b6572730100000000000000000000000000ffffffffff00000000000000"
)

GOLDENS = [
    pytest.param(
        Packet(
            type=Packet.PayloadType.ADD_DEBUG_MARKER_CUBE,
            debug_marker_data=Packet.DebugMarkerData(
                text="marker",
                position=v2225.Vec3(x=1.0, y=2.0, z=3.0),
                color=0x44556677,
                duration_ms=1500,
            ),
        ),
        ADD_CUBE,
        id="add-cube",
    ),
    pytest.param(
        Packet(type=Packet.PayloadType.INVALID, debug_marker_data=None),
        INVALID,
        id="absent-marker",
    ),
    pytest.param(
        Packet(
            type=Packet.PayloadType.CLEAR_DEBUG_MARKERS,
            debug_marker_data=Packet.DebugMarkerData(
                text="",
                position=v2225.Vec3(x=0.0, y=0.0, z=0.0),
                color=-1,
                duration_ms=255,
            ),
        ),
        CLEAR_WITH_MARKER,
        id="marker-on-a-clear",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_clientbound_debug_renderer_is_packet_164(version):
    assert version.PACKETS[164] is version.ClientboundDebugRendererPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_debug_renderer_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_debug_renderer_decodes_from_its_golden(packet, golden):
    assert Packet.from_bytes(golden) == packet
